/**
 * @distilled.cloud/coinflow -- Coinflow payments API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-coinflow/specs/openapi.json`. Everything else in this
 * folder is hand-written.
 *
 * One module per API area (the spec's tags): `authentication`, `checkout`,
 * `customers`, `merchant`, `redeem`, `refund`, `withdraw`, ...
 *
 * @example
 * ```ts
 * import * as Coinflow from "@distilled.cloud/coinflow";
 *
 * const { key } = yield* Coinflow.authentication.getSessionKey({ authUserId: "user-123" });
 * ```
 */
